/*
WITH

	obj AS(
		SELECT
			n.nspname
			,p.proname AS relname
			,2 AS order_
			,FORMAT(
				$$DROP FUNCTION IF EXISTS %I.%I(%s) CASCADE;$$
				,n.nspname
				,p.proname
				,pg_get_function_identity_arguments(p.oid)
			) AS sql_
		FROM pg_proc p
		INNER JOIN pg_namespace n ON p.pronamespace = n.oid
			AND n.nspname = 'aflob_plan'
		-- WHERE p.proname ~* '^plan_'

		UNION ALL

		SELECT
			n.nspname
			,c.relname
			,1 AS order_
			,FORMAT(
				$$DROP TABLE IF EXISTS %I.%I CASCADE;$$
				,n.nspname
				,c.relname
			) AS sql_
		FROM pg_class c
		INNER JOIN pg_namespace n ON c.relnamespace = n.oid
			AND n.nspname = 'aflob_plan'
		WHERE c.relkind = 'r'
			-- AND c.relname ~* '^plan_'
	)

SELECT
	string_agg(
		sql_
		,E'\n'
		ORDER BY nspname
			,order_
			,relname
	)
FROM obj;

-- */




