-- DROP TABLE IF EXISTS aflob_plan.lst_import_type CASCADE;

CREATE TABLE aflob_plan.lst_import_type(
	guid uuid PRIMARY KEY DEFAULT uuid_generate_v4()

	,beskrivelse character varying NOT NULL
	,aktiv integer NOT NULL DEFAULT 1

	,dest_schema text NOT NULL
	,dest_table text NOT NULL
	,source_insert_columns text NOT NULL
	,source_select text NOT NULL
);

/*
INSERT INTO aflob_plan.lst_import_type(
	guid
	,beskrivelse

	,dest_schema
	,dest_table
	,source_insert_columns
	,source_select
) VALUES
	(
		'b4468887-018e-494c-98c6-6e32593df7f0'
		,'HOFOR - Knuder'

		,'aflob'
		,'plan_f_indhold_p'

		,'geom
		,type
		,label
		,label_show
		,label_frame
		,label_callout'
,$$SELECT
	dmp.geom
	,CASE
		WHEN d.kategoriafloeb = 'Stikledning'
			AND d.ejernavn = 'Vejvæsen'
		THEN 'Eksisterende rist'
		ELSE 'Eksisterende dæksel'
	END AS type
	,COALESCE(d.knudenavn, '')
		|| E'\nDK: ' || COALESCE(d.mindaekselkote::text, '')
		|| E'\nBK: ' || COALESCE(NULLIF(d.bundkote, -99)::text, '') AS label
	,CASE
		WHEN d.kategoriafloeb IN('Hovedledning', 'Recipient')
		THEN 1
		ELSE 0
	END AS label_show
	,1 AS label_frame
	,1 AS label_callout
FROM led.f_alle_afl_knuder_p d
	,ST_Intersection(
		ST_Transform(ST_Force2D(d.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE d.knudetype = 'Brønd'
	AND d.datohistorisk IS NULL
	AND d.status NOT IN(
		'Fjernet'
		,'Fjernet (Sløjfet)'
		,'Død'
		,'Ikke i brug'
		,'Projekteret / planlagt'
	)
	AND ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'POINT'$$
	)


	,(
		'99214537-abdf-487b-94ed-69a06a180fa9'
		,'HOFOR - Ledninger'

		,'aflob'
		,'plan_f_indhold_l'

		,'geom
		,type
		,label
		,label_show
		,label_frame
		,label_frame_adjustment
		,label_callout

		,flow_type'
,$$SELECT
	dmp.geom
	,'Eksisterende kloakledning' AS type
	,NULLIF(
		TRIM(
			CASE
				WHEN LOWER(d.roerbetegnelse) NOT IN('uoplyst')
				THEN regexp_replace("roerbetegnelse", '^(øj|ægf|v)', 'ø')
			END
		)
		,'ø'
	) AS label
	,CASE
		WHEN d.kategoriafloeb = 'Stikledning'
				AND d.ejernavn = 'Vejvæsen'
			OR ST_Length(
				ST_Intersection(
					ST_Transform(ST_Force2D(d.geom), 25832)
					,[FRAME]
				)
			) <= 10
		THEN 0
		ELSE 1
	END AS label_show
	,0 AS label_frame
	,7 AS label_frame_adjustment
	,1 AS label_callout

	,CASE
		WHEN d.kategoriafloeb IN('Hovedledning', 'Recipient')
			AND ST_Length(d.geom) >= 2
		THEN 1
		ELSE 0
	END AS flow_type
FROM led.f_alle_afl_ledninger_l d
	,ST_Intersection(
		ST_Transform(ST_Force2D(d.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'LINESTRING'

	AND d.led_datohistorisk IS NULL
	AND d.del_datohistorisk IS NULL
	AND d.status NOT IN(
		'Fjernet'
		,'Fjernet (Sløjfet)'
		,'Død'
		,'Ikke i brug'
		,'Projekteret / planlagt'
	)
	AND d.roerbetegnelse NOT IN(
		'Fiktiv Bygværks Ledning'
	)$$
	)


	,(
		'54b432d0-9157-4705-a0c9-4cbb86852bff'
		,'HOFOR - Bygværker'

		,'aflob'
		,'plan_f_indhold_a'

		,'geom
		,type
		,label
		,label_show
		,label_frame
		,label_callout'
,$$SELECT
	ST_Union(dmp.geom) AS geom
	,'Eksisterende bygværk' AS type
	,COALESCE(d.bygvaerknavn, '')
		|| E'\nDK: ' || COALESCE(MAX(d.maxdaekselkote)::text, '')
		|| E'\nBK: ' || COALESCE(MIN(NULLIF(d.bundkote, -99))::text, '') AS label
	,1 AS label_show
	,1 AS label_frame
	,1 AS label_callout
FROM led.f_afl_kompleksbygvaerk_a d
	,ST_Intersection(
		ST_Transform(ST_Force2D(d.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'POLYGON'

	AND d.datohistorisk IS NULL
	AND d.status NOT IN(
		'Fjernet'
		,'Fjernet (Sløjfet)'
		,'Død'
		,'Ikke i brug'
		,'Projekteret / planlagt'
	)

GROUP BY d.bygvaerknavn$$
	)


	,(
		'faedacfc-be8a-4d77-a793-742b0ff5f8da'
		,'Affaldskurv'

		,'aflob'
		,'plan_f_indhold_p'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Affaldskurv'
FROM cpn.v_affaldskurve_puma_kgb d
	,ST_Intersection(
		ST_Transform(ST_Force2D(d.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'POINT'$$
	)


	,(
		'3a1edc90-0138-4f08-9c2a-636697d11aa8'
		,'Færdselstavle'

		,'aflob'
		,'plan_f_indhold_p'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Færdselstavle' AS type
FROM ctr.v_trafikskilt d
	,ST_Intersection(
		ST_Transform(ST_Force2D(d.sdo_geometry), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_Intersects(d.sdo_geometry, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'POINT'$$
	)


	,(
		'8f663d77-bc34-4777-b0b0-6c953a719ee1'
		,'Træ'

		,'aflob'
		,'plan_f_indhold_p'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Træ' AS type
FROM datafordeleren.v_trae d
	,ST_Intersection(
		ST_Transform(ST_Force2D(d.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'POINT'$$
	)


	,(
		'4664dd47-931b-4308-8109-9f8f0916d4fa'
		,'Stationering'

		,'aflob'
		,'plan_f_indhold_p'

		,'geom
		,type
		,label
		,label_show
		,label_frame
		,label_frame_adjustment
		,label_frame_margin_left
		,label_frame_margin_right
		,label_frame_margin_top
		,label_frame_margin_bottom'
,$$SELECT
	dmp.geom
	,'Stationering' AS type
	,d.distance AS label
	,1 AS label_show
	,0 AS label_frame
	,4 AS label_frame_adjustment
	,0.1 AS label_frame_margin_left
	,0.1 AS label_frame_margin_right
	,0.1 AS label_frame_margin_top
	,0.1 AS label_frame_margin_bottom
FROM ctr.v_stationeringer_20m d
	,ST_Intersection(
		ST_Transform(ST_Force2D(d.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'POINT'$$
	)


	,(
		'4ad1605e-0c80-48af-ad16-d2e924ce9570'
		,'Adgangsadresse'

		,'aflob'
		,'plan_f_indhold_p'

		,'geom
		,type
		,label
		,label_show
		,label_frame
		,label_frame_adjustment
		,label_frame_margin_left
		,label_frame_margin_right
		,label_frame_margin_top
		,label_frame_margin_bottom'
,$$SELECT
	dmp.geom
	,'Adgangsadresse' AS type
	,d.husnr AS label
	,1 AS label_show
	,0 AS label_frame
	,4 AS label_frame_adjustment
	,0.1 AS label_frame_margin_left
	,0.1 AS label_frame_margin_right
	,0.1 AS label_frame_margin_top
	,0.1 AS label_frame_margin_bottom
FROM segis2.f_dar_adgangsadresser d
	,ST_Intersection(
		ST_Transform(ST_Force2D(d.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_Intersects(d.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'POINT'$$
	)

	,(
		'5ae31f60-e4d9-4112-bd34-22228c3e795e'
		,'Helle'

		,'aflob'
		,'plan_f_indhold_l'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Eksisterende forhold' AS type
FROM datafordeleren.v_helle d
	,ST_MakeValid(d.geom) valid(geom)
	,ST_Intersection(
		ST_Transform(ST_Force2D(valid.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_IsValid(valid.geom)
	AND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'LINESTRING'$$
	)


	,(
		'88ded412-5f04-4225-b4df-eb5af93fdf0b'
		,'Vejkant'

		,'aflob'
		,'plan_f_indhold_l'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Eksisterende forhold' AS type
FROM datafordeleren.v_vejkant d
	,ST_MakeValid(d.geom) valid(geom)
	,ST_Intersection(
		ST_Transform(ST_Force2D(valid.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_IsValid(valid.geom)
	AND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'LINESTRING'$$
	)


	,(
		'6aed7510-e160-4070-ba49-3bbedf1b2951'
		,'Chikane'

		,'aflob'
		,'plan_f_indhold_l'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Eksisterende forhold' AS type
FROM datafordeleren.v_chikane d
	,ST_MakeValid(d.geom) valid(geom)
	,ST_Intersection(
		ST_Transform(ST_Force2D(valid.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_IsValid(valid.geom)
	AND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'LINESTRING'$$
	)


	,(
		'5dd3f074-9c66-4b82-bc75-b3b8d9b7d43e'
		,'Hegn'

		,'aflob'
		,'plan_f_indhold_l'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Eksisterende forhold' AS type
FROM datafordeleren.v_hegn d
	,ST_MakeValid(d.geom) valid(geom)
	,ST_Intersection(
		ST_Transform(ST_Force2D(valid.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_IsValid(valid.geom)
	AND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'LINESTRING'$$
	)


	,(
		'fc4feb56-69e6-4819-8312-dc0c5cdd7297'
		,'Parkering'

		,'aflob'
		,'plan_f_indhold_l'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Parkering' AS type
FROM datafordeleren.v_parkering d
	,ST_MakeValid(d.geom) valid(geom)
	,ST_Intersection(
		ST_Transform(ST_Force2D(valid.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_IsValid(valid.geom)
	AND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'LINESTRING'$$
	)


	,(
		'1ba2f8e6-8778-4039-85fb-0b9427d3a136'
		,'Parkeringsplads'

		,'aflob'
		,'plan_f_indhold_l'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Parkeringsplads' AS type
FROM ctr.v_p_pladser d
	,ST_MakeValid(d.sdo_geometry) valid(geom)
	,ST_Intersection(
		ST_Transform(ST_Force2D(valid.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_IsValid(valid.geom)
	AND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'LINESTRING'$$
	)


	,(
		'803a1f15-38d2-4e3a-8fa5-106152b49c2d'
		,'Vandløbsmidte'

		,'aflob'
		,'plan_f_indhold_l'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Vandløbsmidte' AS type
FROM datafordeleren.v_vandloebsmidte d
	,ST_MakeValid(d.geom) valid(geom)
	,ST_Intersection(
		ST_Transform(ST_Force2D(valid.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_IsValid(valid.geom)
	AND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'LINESTRING'$$
	)


	,(
		'cb4d6fd9-5d2f-41e7-839c-7bda3eab2a04'
		,'Vejmidte Label'

		,'aflob'
		,'plan_f_indhold_l'

		,'geom
		,type
		,label
		,label_show
		,label_frame
		,label_frame_adjustment
		,label_frame_margin_left
		,label_frame_margin_right
		,label_frame_margin_top
		,label_frame_margin_bottom'
,$$SELECT
	dmp.geom
	,'Vejmidte Label' AS type
	,d.vejnavn AS label
	,1 AS label_show
	,0 AS label_frame
	,4 AS label_frame_adjustment
	,0.1 AS label_frame_margin_left
	,0.1 AS label_frame_margin_right
	,0.1 AS label_frame_margin_top
	,0.1 AS label_frame_margin_bottom
FROM datafordeleren.v_vejmidte_geodk_labels d
	,ST_MakeValid(d.geom) valid(geom)
	,ST_Intersection(
		ST_Transform(ST_Force2D(valid.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_IsValid(valid.geom)
	AND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'LINESTRING'

	AND d.kommunekode = '0101'$$
	)


	,(
		'a8e45869-6fc0-433a-81f9-688215f75f8a'
		,'Jordstykke'

		,'aflob'
		,'plan_f_indhold_l'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Jordstykke' AS type
FROM (
		SELECT
			ST_LineMerge(
				ST_Split(
					ST_Union(
						ST_Intersection(
							ST_ExteriorRing(dr.geom)
							,[FRAME]
						)
					)
					,ST_Union(dp.geom)
				)
			) AS geom
		FROM mat.f_kk_mu_jordstykke d
			,ST_MakeValid(d.geom) valid(geom)
			,ST_Dump(
				ST_Transform(
					ST_Force2D(valid.geom)
					,25832
				)
			) dmp
			,ST_DumpRings(dmp.geom) dr
			,ST_DumpPoints(dmp.geom) dp
		WHERE ST_IsValid(valid.geom)
			AND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))
	) i
	,ST_Dump(i.geom) dmp
WHERE i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'LINESTRING'$$
	)




	,(
		'26db72b5-95fb-4dd0-828e-9282598ec098'
		,'Bygning'

		,'aflob'
		,'plan_f_indhold_a'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Bygning' AS type
FROM datafordeleren.v_bygning_opr d
	,ST_MakeValid(d.geom) valid(geom)
	,ST_Intersection(
		ST_Transform(ST_Force2D(valid.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_IsValid(valid.geom)
	AND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'POLYGON'$$
	)


	,(
		'afa36b70-5ed8-4a82-83ae-3583553e0e25'
		,'Afmærkning'

		,'aflob'
		,'plan_f_indhold_a'

		,'geom
		,type'
,$$SELECT
	dmp.geom
	,'Eksisterende forhold' AS type
FROM ctr.f_afmaerkning d
	,ST_MakeValid(d.sdo_geometry) valid(geom)
	,ST_Intersection(
		ST_Transform(ST_Force2D(valid.geom), 25832)
		,[FRAME]
	) i(geom)
	,ST_Dump(i.geom) dmp
WHERE ST_IsValid(valid.geom)
	AND ST_Intersects(valid.geom, ST_Transform([BUFFER], 25832))
	AND i.geom IS NOT NULL
	AND NOT(ST_IsEmpty(i.geom))
	AND GeometryType(dmp.geom) = 'POLYGON'

	AND d.type IN(
		'30' -- Hvidafmærkning
		,'31' -- Fodgængerfelt
		,'32' -- Parkering
		,'50' -- Servicemarkering
		,'60' -- Pileafmærkning
		,'80' -- Symboler på kørebane
	)$$
	);
-- */